import React, { useEffect, useRef } from 'react';

const HolographicGlobe = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let animationFrameId;
    let width = (canvas.width = canvas.parentElement.clientWidth || 500);
    let height = (canvas.height = canvas.parentElement.clientHeight || 500);

    const handleResize = () => {
      if (canvas.parentElement) {
        width = canvas.width = canvas.parentElement.clientWidth;
        height = canvas.height = canvas.parentElement.clientHeight;
      }
    };
    window.addEventListener('resize', handleResize);

    let rotationAngle = 0;
    const globeRadius = Math.min(width, height) * 0.38;

    // Approximate Continent lat/lng clusters
    const continents = [
      // North America
      { lat: 0.7, lng: -1.7 }, { lat: 0.8, lng: -1.9 }, { lat: 0.6, lng: -1.5 }, { lat: 0.5, lng: -1.4 },
      // Europe
      { lat: 0.9, lng: 0.2 }, { lat: 0.8, lng: 0.3 }, { lat: 0.95, lng: 0.4 }, { lat: 0.85, lng: 0.1 },
      // Asia
      { lat: 0.6, lng: 1.8 }, { lat: 0.7, lng: 2.1 }, { lat: 0.5, lng: 1.5 }, { lat: 0.4, lng: 2.3 },
      // South America
      { lat: -0.2, lng: -1.0 }, { lat: -0.4, lng: -1.1 }, { lat: -0.6, lng: -0.9 },
      // Africa
      { lat: 0.1, lng: 0.3 }, { lat: -0.3, lng: 0.4 }, { lat: 0.3, lng: 0.5 },
      // Australia
      { lat: -0.5, lng: 2.3 }, { lat: -0.4, lng: 2.5 }
    ];

    // Convert continents to 3D points
    const landPoints = continents.map(c => ({
      x: globeRadius * Math.cos(c.lat) * Math.cos(c.lng),
      y: globeRadius * Math.sin(c.lat),
      z: globeRadius * Math.cos(c.lat) * Math.sin(c.lng),
    }));

    // Grid Latitude / Longitude 3D Mesh
    const meshPoints = [];
    const latLines = 14;
    const lngLines = 20;

    for (let i = 0; i <= latLines; i++) {
      const lat = (Math.PI * i) / latLines - Math.PI / 2;
      for (let j = 0; j < lngLines; j++) {
        const lng = (2 * Math.PI * j) / lngLines;
        meshPoints.push({
          x: globeRadius * Math.cos(lat) * Math.cos(lng),
          y: globeRadius * Math.sin(lat),
          z: globeRadius * Math.cos(lat) * Math.sin(lng),
        });
      }
    }

    // Interactive Nodes around Globe
    const activeNodes = [
      { name: 'GitHub Sync Node', lat: 0.7, lng: -1.7, color: '#635985' },
      { name: 'Resume Parser', lat: 0.8, lng: 0.3, color: '#443C68' },
      { name: 'Trust Engine Radar', lat: 0.6, lng: 1.8, color: '#635985' },
      { name: 'SkillSwap Pairing', lat: -0.4, lng: 2.3, color: '#9B8CBF' },
    ];

    let pulseTime = 0;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      rotationAngle += 0.005;
      pulseTime += 0.03;

      // 1. Draw Outer Orbit Rings
      ctx.save();
      ctx.translate(centerX, centerY);

      // Main Tilted Orbit Ring
      ctx.beginPath();
      ctx.ellipse(0, 0, globeRadius * 1.38, globeRadius * 0.45, Math.PI / 6, 0, Math.PI * 2);
      ctx.strokeStyle = '#635985';
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.35;
      ctx.stroke();

      // Satellite Orbiting on Main Ring
      const satAngle = rotationAngle * 1.5;
      const satX = Math.cos(satAngle) * globeRadius * 1.38;
      const satY = Math.sin(satAngle) * globeRadius * 0.45;
      ctx.beginPath();
      ctx.arc(satX, satY, 4, 0, Math.PI * 2);
      ctx.fillStyle = '#EFEBF8';
      ctx.globalAlpha = 0.85;
      ctx.fill();

      // Counter Rotating Inner Orbit Ring
      ctx.beginPath();
      ctx.ellipse(0, 0, globeRadius * 1.18, globeRadius * 0.38, -Math.PI / 4, 0, Math.PI * 2);
      ctx.strokeStyle = '#443C68';
      ctx.lineWidth = 1.2;
      ctx.globalAlpha = 0.3;
      ctx.stroke();

      ctx.restore();

      // 2. Project 3D Latitude/Longitude Mesh Points
      const cos = Math.cos(rotationAngle);
      const sin = Math.sin(rotationAngle);

      meshPoints.forEach((p) => {
        const rx = p.x * cos - p.z * sin;
        const rz = p.x * sin + p.z * cos;
        const scale = 450 / (450 + rz);

        if (rz < 60) {
          ctx.beginPath();
          ctx.arc(centerX + rx * scale, centerY + p.y * scale, 1.2 * scale, 0, Math.PI * 2);
          ctx.fillStyle = '#635985';
          ctx.globalAlpha = Math.max(0.1, (1 - rz / 250) * 0.35);
          ctx.fill();
        }
      });

      // 3. Project Continent Landmass Dots
      landPoints.forEach((p) => {
        const rx = p.x * cos - p.z * sin;
        const rz = p.x * sin + p.z * cos;
        const scale = 450 / (450 + rz);

        if (rz < 80) {
          ctx.beginPath();
          ctx.arc(centerX + rx * scale, centerY + p.y * scale, 2.5 * scale, 0, Math.PI * 2);
          ctx.fillStyle = '#EFEBF8';
          ctx.globalAlpha = Math.max(0.2, (1 - rz / 250) * 0.7);
          ctx.fill();
        }
      });

      // 4. Project Active Holographic AI Nodes & Connection Arcs
      activeNodes.forEach((node) => {
        const nx = globeRadius * Math.cos(node.lat) * Math.cos(node.lng);
        const ny = globeRadius * Math.sin(node.lat);
        const nz = globeRadius * Math.cos(node.lat) * Math.sin(node.lng);

        const rx = nx * cos - nz * sin;
        const rz = nx * sin + nz * cos;
        const scale = 450 / (450 + rz);

        if (rz < 90) {
          const px = centerX + rx * scale;
          const py = centerY + ny * scale;

          // Node Pulse Ring
          const pulseR = (Math.sin(pulseTime) + 1) * 6 + 4;
          ctx.beginPath();
          ctx.arc(px, py, pulseR, 0, Math.PI * 2);
          ctx.strokeStyle = '#635985';
          ctx.lineWidth = 1;
          ctx.globalAlpha = 0.4;
          ctx.stroke();

          // Node Core Point
          ctx.beginPath();
          ctx.arc(px, py, 4.5, 0, Math.PI * 2);
          ctx.fillStyle = '#EFEBF8';
          ctx.globalAlpha = 0.9;
          ctx.fill();
        }
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="w-full h-full min-h-[380px] sm:min-h-[480px] relative flex items-center justify-center">
      <canvas ref={canvasRef} className="w-full h-full max-w-[550px] max-h-[550px]" />
    </div>
  );
};

export default HolographicGlobe;
